// Structural inventory-order regression, not a financial oracle.
// The public signed fixture was generated by the authorized isolated browser
// workflow from the app's already published synthetic sample. No private key or
// private account source is included. Producer helpers only construct input;
// the independent checker imports none of them and no new signing occurs here.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { sampleInput } from '../src/calculator.js';
import { captureSource, reconcileAccount, makeReconciliationArtifact } from '../src/reconciliation.js';
import { verifyReconciliation } from '../scripts/verify-reconciliation.mjs';

const profile = JSON.parse("{\"schema_version\":\"n170.verify.track-record.v4\",\"profile_id\":\"04bff717f25b3402750d329a2fe1742da37a0814ae58f64aa00df962112edc6d\",\"display_name\":\"Synthetic offline-check workflow\",\"public_key\":\"BNuSwmAkOQIx5trTBw-pQn2KJ130I1GxgxMDL5twIZyYBwWmhjOXcxx3U6DPYcYL4JT3D3WWFmCTBgWr68gTq1c\",\"stamps\":[{\"payload\":{\"schema_version\":\"n170.verify.performance-stamp.v4\",\"calculation_version\":\"2.0.0\",\"sequence\":1,\"profile_id\":\"04bff717f25b3402750d329a2fe1742da37a0814ae58f64aa00df962112edc6d\",\"display_name\":\"Synthetic offline-check workflow\",\"previous_sha256\":null,\"source_kind\":\"synthetic_demo\",\"provider_authenticated\":false,\"independent_timestamp\":false,\"period\":{\"start\":\"2025-01-02\",\"end\":\"2025-01-07\"},\"periods_per_year\":252,\"relative_returns\":[{\"start\":\"2025-01-02\",\"end\":\"2025-01-03\",\"return_e8\":1000000},{\"start\":\"2025-01-03\",\"end\":\"2025-01-06\",\"return_e8\":1009901},{\"start\":\"2025-01-06\",\"end\":\"2025-01-07\",\"return_e8\":-1000000}],\"coverage\":{\"nav_observations\":4,\"return_observations\":3,\"external_cash_flow_count\":1},\"metrics\":{\"total_return_twr_e8\":999800,\"annualized_volatility_e8\":null,\"max_drawdown_e8\":-1000000},\"serialization_version\":\"1.0.0\",\"event_type\":\"performance\",\"correction\":null,\"provenance\":{\"kind\":\"supplied_file\",\"format\":\"n170\",\"original_sha256\":\"9964bb722d6eb84d50ff65864cbc45fa8765c065303d18b9b820e38f75b3b803\",\"source_sha256\":\"9964bb722d6eb84d50ff65864cbc45fa8765c065303d18b9b820e38f75b3b803\",\"normalized_sha256\":\"9964bb722d6eb84d50ff65864cbc45fa8765c065303d18b9b820e38f75b3b803\",\"mapping\":[{\"field\":\"Observation date\",\"column\":\"date\"},{\"field\":\"Net asset value\",\"column\":\"nav\"},{\"field\":\"External flows\",\"column\":\"external_flow\"}],\"account_scope\":\"Published synthetic workflow only\",\"currency\":\"USD\",\"completeness\":\"not_established\",\"corrections\":[],\"reviewed\":true}},\"sha256\":\"6309914f8c0dcc5e0ecf2493b0a1d7047db34082a21d48e755e88637df02fe56\",\"signature\":\"QJ3u4o8muK-fja-ETZPTvXKmXbMQphLdliw44RY1EJrob9qr-lrEWR9yz1ushb0IStC1EakHv0Nhv7jycPr5sg\"}]}");

const stamp = profile.stamps[0];
const encodedProfile = JSON.stringify(profile);
const digest = value => createHash('sha256').update(value).digest('hex');

async function input() {
  assert.equal(digest(sampleInput), stamp.payload.provenance.source_sha256);
  const options = {
    input: sampleInput, original: sampleInput, fileName: 'published-synthetic-sample.csv', format: 'n170',
    currency: stamp.payload.provenance.currency, frequency: stamp.payload.periods_per_year,
    accountScope: stamp.payload.provenance.account_scope, flowTimingConfirmed: true,
    expectedSchedule: 'observed_boundaries', flowActivity: 'reviewed_no_hidden', flowTiming: 'interval_end',
  };
  const artifact = makeReconciliationArtifact(await reconcileAccount(options));
  const excluded = await captureSource({ text: 'EXCLUDED AUTHOR STRUCTURAL SOURCE\n', fileName: 'excluded-synthetic.txt', format: 'auto', currency: options.currency, frequency: options.frequency });
  Object.assign(excluded, { disposition: 'excluded', reason: 'Unrelated synthetic input retained only for the inventory-order regression.' });
  assert.notEqual(excluded.sha256, artifact.reconciliation.source_inventory[0].sha256);
  return { artifact, excluded };
}

const check = artifact => verifyReconciliation(encodedProfile, JSON.stringify(artifact), stamp.sha256);

test('a sole active source after a reasoned exclusion retains order and all bindings', async () => {
  const { artifact, excluded } = await input();
  const original = check(artifact);
  assert.equal(original.status, 'VERIFIED_UNDER_OWNER_ASSERTIONS');
  const originalDependencies = structuredClone(artifact.reconciliation.intervals.map(interval => interval.dependencies));
  artifact.reconciliation.source_inventory.unshift(excluded);
  const result = check(artifact);
  assert.equal(result.status, 'VERIFIED_UNDER_OWNER_ASSERTIONS');
  assert.deepEqual(result.selected_event, original.selected_event);
  assert.deepEqual(result.checks, original.checks);
  assert.deepEqual(result.source_decisions.map(source => [source.ordinal, source.disposition, source.byte_binding]), [[1, 'excluded', 'matched'], [2, 'active', 'matched']]);
  assert.deepEqual(artifact.reconciliation.intervals.map(interval => interval.dependencies), originalDependencies);
  assert.equal(result.checks.private_intervals, true);
});

test('reordering cannot rebind an active interval to the excluded source', async () => {
  const { artifact, excluded } = await input();
  artifact.reconciliation.source_inventory.unshift(excluded);
  artifact.reconciliation.intervals[0].dependencies[0].source_sha256 = excluded.sha256;
  const result = check(artifact);
  assert.equal(result.status, 'MISMATCH');
  assert.ok(result.reasons.includes('PRIVATE_DEPENDENCY_MISMATCH'));
  assert.equal(result.checks.private_intervals, false);
  assert.deepEqual(result.source_decisions.map(source => source.disposition), ['excluded', 'active']);
});

test('zero or multiple active sources remain invalid', async () => {
  const { artifact, excluded } = await input();
  const zero = structuredClone(artifact);
  Object.assign(zero.reconciliation.source_inventory[0], { disposition: 'excluded', reason: excluded.reason });
  const multiple = structuredClone(artifact);
  multiple.reconciliation.source_inventory.push(structuredClone(multiple.reconciliation.source_inventory[0]));
  for (const supplied of [zero, multiple]) {
    const result = check(supplied);
    assert.equal(result.status, 'INVALID_INPUT');
    assert.deepEqual(result.reasons, ['INVALID_ACTIVE_SOURCE']);
  }
});
